#偵測邏輯 檔案
#抽象類別&實作類別
import os
os.environ['TF_CPP_MIN_LOG_LEVEL'] = '2'
from abc import ABC, abstractmethod
import base64
from pathlib import Path
import numpy as np
import cv2
from operator import itemgetter
from keras.models import load_model
from keras import Layer
from keras.ops import argmax,convert_to_numpy 

#偵測抽象基底類別
class DetectAbstract(ABC):
    def __init__(self):
        self.sucess :bool = False  #辨識是否成功
        self.message :str = ""     #要傳給前端的訊息
        self.result :str = ""      #辨識結果
    
    @abstractmethod
    def StartDetect(self,imgRaw) -> None :
        #實作程式碼....
        return
          
    
#實作類別
class Detect(DetectAbstract):
    def __init__(self):
        super().__init__()
        self.imgwidth :int = 0
        self.imgheight :int = 0
        
        
    def Base64ToNumpy(self,imgRaw:str) -> np:
        #把Base64字串轉換為BGR Numpy陣列處理方法
        base64_data = imgRaw.split(',')[1]
        image_bytes = base64.b64decode(base64_data)
        img_1D_Array = np.frombuffer(image_bytes, np.uint8)
        #轉換後陣列通道順序 BGRA
        img_BGRA_Array = cv2.imdecode(img_1D_Array, cv2.IMREAD_UNCHANGED)
        png_Alpha = img_BGRA_Array[:,:,3] /255
        background_Alpha =  1 - png_Alpha
        self.imgwidth = img_BGRA_Array.shape[1]
        self.imgheight = img_BGRA_Array.shape[0]
        white_Background = np.full((self.imgheight, self.imgwidth),255,dtype=np.uint8)
        #B通道轉換
        img_BGRA_Array[:,:,0] = img_BGRA_Array[:,:,0] * png_Alpha + white_Background * background_Alpha
        #G通道轉換
        img_BGRA_Array[:,:,1] = img_BGRA_Array[:,:,1] * png_Alpha + white_Background * background_Alpha
        #R通道轉換
        img_BGRA_Array[:,:,2] = img_BGRA_Array[:,:,2] * png_Alpha + white_Background * background_Alpha
        return img_BGRA_Array[:,:,:3]
    
    
    def GetWriteNumber(self,imgBGRArray:np):  
        #取得數字位置座標處理方法
        img_GRAY_Array = cv2.cvtColor(imgBGRArray,cv2.COLOR_BGR2GRAY)
        _,img_Binary_Array = cv2.threshold(img_GRAY_Array,127,255,cv2.THRESH_BINARY_INV)
        contours,_ = cv2.findContours(img_Binary_Array,cv2.RETR_EXTERNAL,cv2.CHAIN_APPROX_SIMPLE)
        contours_List_Sorted = []
        for contour in contours:
            x,y,w,h = cv2.boundingRect(contour)
            contours_List_Sorted.append((x,y,w,h))
        contours_List_Sorted = sorted(contours_List_Sorted,key=itemgetter(0))
        return contours_List_Sorted,img_Binary_Array
    
    
    def Check(self,contours:list) -> bool:
        #檢查手寫數字是否符合限制
        if(len(contours) > 2):
            self.sucess = False
            self.message = "偵測到超過兩位數，無法進行辨識。"
            self.result = ""
            return False
        elif(len(contours) == 1):
            return True
        else:
            x1,y1,w1,h1 = contours[0]
            x2,y2,w2,h2 = contours[1]
            if(x2 <= (x1+w1)): 
                self.sucess = False
                self.message = "兩個位數距離太相近，無法辨識。"
                self.result = ""
                return False
            return True
      
                                  
    def Preprocessing(self,img_Array:np,contours:list[tuple])-> np:
        #模型輸入資料前處理方法
        model_Input_List = []
        for contour in contours:            
            black_Background = np.full((self.imgheight, self.imgwidth),0,dtype=np.uint8)
            x,y,w,h = contour
            # w,h 不需要減1
            number = img_Array[y:y+h,x:x+w]
            insert_X_Start = int((self.imgwidth/2)-(w/2))
            insert_Y_Start = int((self.imgheight/2)-(h/2))
            black_Background[insert_Y_Start:insert_Y_Start+h,insert_X_Start:insert_X_Start+w] = number
            #注意 resize() 對於陣列類型只支援:np.uint8、np.uint16、np.float32、np.float64
            resized = cv2.resize(black_Background,(28,28),interpolation=cv2.INTER_AREA)
            #增強數字
            _,resized = cv2.threshold(resized,5,255,cv2.THRESH_BINARY)
            resized = (resized/255).astype("float32").reshape(28,28,1)
            model_Input_List.append(resized)
        model_Input_Array = np.array(model_Input_List)
        return model_Input_Array
     
    
    def Idenity(self,model_Input:np)->None:
        #使用模型進行辨識
        class dim_splitter(Layer):  
            def __init__(self,**kawgs):
                super().__init__(**kawgs)
            def call(self,inputs):
                inputs_split_1 = inputs[:,:,:,0:100:2]
                inputs_split_2 = inputs[:,:,:,1:100:2]
                return inputs_split_1,inputs_split_2
        cwdPath = Path(__file__).resolve().parent
        model = load_model(cwdPath/"mymodel.keras",custom_objects={"dim_splitter":dim_splitter})
        result_Tensor = argmax(model(model_Input,training=False),axis=1)
        result = ""
        for i in result_Tensor:
            result+=str(int(i))
        self.sucess = True
        self.result = result
        self.message = "辨識成功"
       
        
    def StartDetect(self,imgRaw:str) -> None:
        #開始辨識流程
        img_BGR_Array = self.Base64ToNumpy(imgRaw)
        contours_list,img_Binary_Array = self.GetWriteNumber(img_BGR_Array)
        if not(self.Check(contours_list)): return
        model_Input = self.Preprocessing(img_Binary_Array,contours_list)
        self.Idenity(model_Input)
 
    
if  __name__ == "__main__" :
    # 350x350 PNG 數字3 red 包含透明背景
    test_one_number = "data:image/png;base64,"
